<?php
/** Resource packages and explicit, auditable capacity purchases. No payment is charged here. */
class pbx_reseller {
    private PDO $db;
    public function __construct(?PDO $db=null){$this->db=$db??database::new()->db;$this->db->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);}
    private function q(string $sql,array $params=[]): PDOStatement {$s=$this->db->prepare($sql);foreach(array_values($params)as$i=>$v)$s->bindValue($i+1,$v,$v===null?PDO::PARAM_NULL:(is_bool($v)?PDO::PARAM_BOOL:(is_int($v)?PDO::PARAM_INT:PDO::PARAM_STR)));$s->execute();return $s;}
    private function grant(string $permission): bool {$id=$_SESSION['user_uuid']??'';return is_uuid($id)&&(bool)$this->q("select 1 from v_users u join v_user_groups ug on ug.user_uuid=u.user_uuid join v_group_permissions p on p.group_uuid=ug.group_uuid where u.user_uuid=? and u.user_enabled='true' and p.permission_name=? and p.permission_assigned='true' limit 1",[$id,$permission])->fetchColumn();}
    private function actor(): string {if(empty($_SESSION['authorized'])||!$this->grant('pbx_service_view'))throw new DomainException('Administrator access is required.');return $_SESSION['user_uuid'];}
    public function manager(): bool {return !empty($_SESSION['authorized'])&&$this->grant('pbx_reseller_manage')&&($this->platform()||(bool)$this->q('select 1 from v_pbx_tenants where owner_user_uuid=? and enabled',[$_SESSION['user_uuid']])->fetchColumn());}
    private function platform(): bool {return $this->grant('pbx_tenant_manage');}
    private function manage(): string {$actor=$this->actor();if(!$this->manager())throw new DomainException('Package management permission is required.');return $actor;}
    private function id($id): string {if(!is_string($id)||!is_uuid($id))throw new InvalidArgumentException('Choose an existing item.');return $id;}
    private function integer(array $in,string $key,int $min,int $max,int $default=0): int {$v=$in[$key]??$default;$n=filter_var($v,FILTER_VALIDATE_INT,['options'=>['min_range'=>$min,'max_range'=>$max]]);if(is_bool($v)||$n===false)throw new InvalidArgumentException('Enter a valid '.str_replace('_',' ',$key).'.');return $n;}
    private function audit(string $event,array $data=[],?string $domain=null,?string $tenant=null): void {$this->q('insert into v_pbx_reseller_audit(event_uuid,actor_uuid,domain_uuid,tenant_uuid,event_type,details) values(?,?,?,?,?,?::jsonb)',[uuid(),$_SESSION['user_uuid'],$domain,$tenant,$event,json_encode($data,JSON_THROW_ON_ERROR)]);}
    private function tenant(string $id): array {$actor=$this->actor();$r=$this->q('select * from v_pbx_tenants where tenant_uuid=? and enabled',[$this->id($id)])->fetch(PDO::FETCH_ASSOC);if(!$r||(!$this->platform()&&$r['owner_user_uuid']!==$actor&&!($this->manager()&&($r['reseller_user_uuid']??null)===$actor)))throw new DomainException('Tenant access denied.');return $r;}
    private function service(string $id): array {$actor=$this->actor();$r=$this->q("select s.*,t.owner_user_uuid,t.reseller_user_uuid from v_pbx_services s join v_pbx_tenants t using(tenant_uuid) join v_domains d using(domain_uuid) where s.domain_uuid=? and t.enabled and d.domain_enabled='true'",[$this->id($id)])->fetch(PDO::FETCH_ASSOC);if(!$r||(!$this->platform()&&$r['owner_user_uuid']!==$actor&&!($this->manager()&&($r['reseller_user_uuid']??null)===$actor)))throw new DomainException('PBX access denied.');return $r;}
    private function plan(string $id,bool $write=false): array {$r=$this->q('select * from v_pbx_resource_plans where plan_uuid=?',[$this->id($id)])->fetch(PDO::FETCH_ASSOC);if(!$r||($write&&!$this->platform()&&$r['owner_user_uuid']!==$_SESSION['user_uuid']))throw new DomainException('Package unavailable.');return $r;}
    /** Operator-approved wholesale ceiling; delegated resellers cannot mint capacity. */
    public function ceiling(): ?array {
        $this->actor();$policy=$this->policy();if(!$policy['hosted']||$this->platform())return null;$actor=$_SESSION['user_uuid'];
        $parent=$this->q('select * from v_pbx_tenants where owner_user_uuid=? and enabled order by created_at limit 1',[$actor])->fetch(PDO::FETCH_ASSOC);if(!$parent)throw new DomainException('An active reseller workspace is required.');$approved=$parent['resource_plan_assigned_by']??null;$operator=$approved&&(bool)$this->q("select 1 from v_users u join v_user_groups ug using(user_uuid) join v_group_permissions gp using(group_uuid) where u.user_uuid=? and u.user_enabled='true' and gp.permission_name='pbx_tenant_manage' and gp.permission_assigned='true'",[$approved])->fetchColumn();$plan=$operator?$parent['resource_plan_uuid']:$policy['default_plan_uuid'];if(!$plan)throw new DomainException('Ask the instance administrator to assign your reseller resource package.');$p=$this->plan($plan);if(!$p['enabled'])throw new DomainException('Your reseller resource package is unavailable.');
        $extra=$this->q("select coalesce(max(e.extra_extensions),0) extensions,coalesce(max(e.extra_calls),0) calls from v_pbx_service_entitlements e join v_pbx_services s using(domain_uuid) where s.tenant_uuid=? and exists(select 1 from v_pbx_resource_orders o join v_user_groups ug on ug.user_uuid=o.approved_by join v_group_permissions gp using(group_uuid) where o.domain_uuid=e.domain_uuid and o.status='approved' and gp.permission_name='pbx_tenant_manage' and gp.permission_assigned='true')",[$parent['tenant_uuid']])->fetch(PDO::FETCH_ASSOC);
        return ['extension_limit'=>(int)$p['extension_limit']+(int)$extra['extensions'],'concurrent_calls'=>(int)$p['concurrent_calls']+(int)$extra['calls']];
    }
    private function withinCeiling(int $extensions,int $calls): void {$ceiling=$this->ceiling();if($ceiling&&($extensions>$ceiling['extension_limit']||$calls>$ceiling['concurrent_calls']))throw new DomainException('This exceeds your operator-approved reseller allowance. Request additional wholesale capacity from the instance administrator.');}
    public function setReseller(array $input): void {
        $this->manage();if(!$this->platform())throw new DomainException('Only the instance administrator can appoint a reseller.');$user=$this->id($input['user_uuid']??'');$enabled=filter_var($input['enabled']??false,FILTER_VALIDATE_BOOLEAN,FILTER_NULL_ON_FAILURE);if($enabled===null)throw new InvalidArgumentException('Choose enabled or disabled.');$owner=$this->q("select u.domain_uuid from v_users u join v_pbx_tenants t on t.owner_user_uuid=u.user_uuid where u.user_uuid=? and u.user_enabled='true' and t.enabled",[$user])->fetchColumn();if(!$owner)throw new InvalidArgumentException('Choose an active tenant owner.');
        $this->db->beginTransaction();try{$this->q("select pg_advisory_xact_lock(hashtext('openweb-reseller-role'))");$group=$this->q("select group_uuid from v_groups where group_name='reseller' and domain_uuid is null")->fetchColumn();if(!$group){$group=uuid();$this->q("insert into v_groups(group_uuid,group_name,group_description) values(?,'reseller','Manages own client tenants and resource packages')",[$group]);$this->q("insert into v_group_permissions(group_permission_uuid,group_uuid,group_name,permission_name,permission_assigned) values(?,?,'reseller','pbx_reseller_manage','true')",[uuid(),$group]);}
        if($enabled)$this->q("insert into v_user_groups(user_group_uuid,domain_uuid,user_uuid,group_uuid,group_name) select ?,?,?,?,'reseller' where not exists(select 1 from v_user_groups where user_uuid=? and group_uuid=?)",[uuid(),$owner,$user,$group,$user,$group]);else $this->q('delete from v_user_groups where user_uuid=? and group_uuid=?',[$user,$group]);$this->audit('reseller_role_changed',['user_uuid'=>$user,'enabled'=>$enabled]);$this->db->commit();}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
    }
    public function policy(?array $input=null): array {
        $this->actor();if($input!==null){$this->manage();if(!$this->platform())throw new DomainException('Only the instance administrator can change hosting policy.');$hosted=filter_var($input['hosted']??false,FILTER_VALIDATE_BOOLEAN,FILTER_NULL_ON_FAILURE);if($hosted===null)throw new InvalidArgumentException('Choose hosted or self hosted.');$plan=$input['default_plan_uuid']??null;if($plan==='')$plan=null;if($plan!==null){$p=$this->plan($plan);if(!$p['enabled'])throw new InvalidArgumentException('Choose an enabled default package.');}$this->q('update v_pbx_reseller_settings set hosted=?,default_plan_uuid=? where singleton',[$hosted,$plan]);$this->audit('hosting_policy',['hosted'=>$hosted,'default_plan_uuid'=>$plan]);}
        return $this->q('select hosted,default_plan_uuid from v_pbx_reseller_settings where singleton')->fetch(PDO::FETCH_ASSOC)?:['hosted'=>false,'default_plan_uuid'=>null];
    }
    public function plans(): array {$actor=$this->actor();if($this->manager())return $this->q('select * from v_pbx_resource_plans where '.($this->platform()?'true':'owner_user_uuid=?').' order by plan_name',$this->platform()?[]:[$actor])->fetchAll(PDO::FETCH_ASSOC);return $this->q('select p.* from v_pbx_resource_plans p where p.enabled and (exists(select 1 from v_pbx_tenants t where t.owner_user_uuid=? and t.enabled and t.resource_plan_uuid=p.plan_uuid) or p.plan_uuid=(select default_plan_uuid from v_pbx_reseller_settings where singleton)) order by p.plan_name',[$actor])->fetchAll(PDO::FETCH_ASSOC);}
    public function savePlan(array $in): string {
        $actor=$this->manage();$existing=!empty($in['plan_uuid'])?$this->plan($in['plan_uuid'],true):null;$id=$existing['plan_uuid']??uuid();$name=$in['plan_name']??'';if(!is_string($name)||trim($name)===''||mb_strlen($name)>100||preg_match('/[\x00-\x1f]/',$name))throw new InvalidArgumentException('Enter a package name.');$currency=$in['currency']??'ZAR';if(!is_string($currency)||!preg_match('/^[A-Z]{3}$/D',$currency))throw new InvalidArgumentException('Enter a three letter currency code.');$enabled=filter_var($in['enabled']??true,FILTER_VALIDATE_BOOLEAN,FILTER_NULL_ON_FAILURE);if($enabled===null)throw new InvalidArgumentException('Choose whether the package is enabled.');
        $values=[trim($name),$this->integer($in,'extension_limit',1,10000,10),$this->integer($in,'concurrent_calls',1,10000,5),$this->integer($in,'extension_price_cents',0,100000000),$this->integer($in,'call_price_cents',0,100000000),$currency,$enabled];
        $this->withinCeiling($values[1],$values[2]);$this->db->beginTransaction();try{if($existing)$this->q('update v_pbx_resource_plans set plan_name=?,extension_limit=?,concurrent_calls=?,extension_price_cents=?,call_price_cents=?,currency=?,enabled=? where plan_uuid=?',[...$values,$id]);else $this->q('insert into v_pbx_resource_plans(plan_name,extension_limit,concurrent_calls,extension_price_cents,call_price_cents,currency,enabled,plan_uuid,owner_user_uuid) values(?,?,?,?,?,?,?,?,?)',[...$values,$id,$actor]);$this->audit('package_saved',['plan_uuid'=>$id]);$this->db->commit();}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}return $id;
    }
    public function assignTenant(array $in): void {$this->manage();$t=$this->tenant($in['tenant_uuid']??'');$p=$this->plan($in['plan_uuid']??'',true);if(!$p['enabled'])throw new InvalidArgumentException('Choose an enabled package.');if(!$this->platform()&&$t['owner_user_uuid']===($_SESSION['user_uuid']??''))throw new DomainException('Your wholesale package is managed by the instance administrator.');$this->withinCeiling((int)$p['extension_limit'],(int)$p['concurrent_calls']);$this->db->beginTransaction();try{$this->q('select tenant_uuid from v_pbx_tenants where tenant_uuid=? for update',[$t['tenant_uuid']]);if($this->q('select 1 from v_pbx_service_entitlements e join v_pbx_services s using(domain_uuid) where s.tenant_uuid=? and e.restore_hold limit 1',[$t['tenant_uuid']])->fetchColumn())throw new DomainException('A backup restore is in progress. Try again when it finishes.');$this->q('update v_pbx_tenants set resource_plan_uuid=?,resource_plan_assigned_by=? where tenant_uuid=?',[$p['plan_uuid'],$_SESSION['user_uuid'],$t['tenant_uuid']]);$this->audit('tenant_package_assigned',['plan_uuid'=>$p['plan_uuid']],null,$t['tenant_uuid']);$this->db->commit();}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}}
    public function assign(array $in): void {
        $actor=$this->manage();$service=$this->service($in['domain_uuid']??'');if(!$this->platform()&&$service['owner_user_uuid']===$actor)throw new DomainException('Your wholesale PBX package is managed by the instance administrator.');$p=$this->plan($in['plan_uuid']??'',true);if(!$p['enabled'])throw new InvalidArgumentException('Choose an enabled package.');$hosted=$this->policy()['hosted'];
        $this->db->beginTransaction();try{$this->q("select pg_advisory_xact_lock(hashtextextended('openweb-extensions:'||?::text,0))",[$service['domain_uuid']]);$old=$this->q('select * from v_pbx_service_entitlements where domain_uuid=? for update',[$service['domain_uuid']])->fetch(PDO::FETCH_ASSOC);if(!empty($old['restore_hold']))throw new DomainException('A backup restore is in progress. Try again when it finishes.');$extraExt=(int)($old['extra_extensions']??0);$extraCalls=(int)($old['extra_calls']??0);$this->withinCeiling((int)$p['extension_limit']+$extraExt,(int)$p['concurrent_calls']+$extraCalls);$used=(int)$this->q('select count(*) from v_extensions where domain_uuid=?',[$service['domain_uuid']])->fetchColumn();if($used>(int)$p['extension_limit']+$extraExt)throw new DomainException('This package has fewer extensions than this PBX already uses. Choose a larger package.');
        $this->q('insert into v_pbx_service_entitlements(domain_uuid,plan_uuid,extension_limit,concurrent_calls,billable,updated_by) values(?,?,?,?,?,?) on conflict(domain_uuid) do update set plan_uuid=excluded.plan_uuid,extension_limit=excluded.extension_limit,concurrent_calls=excluded.concurrent_calls,billable=excluded.billable,updated_by=excluded.updated_by,updated_at=now()',[$service['domain_uuid'],$p['plan_uuid'],(int)$p['extension_limit'],(int)$p['concurrent_calls'],(bool)$hosted,$actor]);$this->capacityDialplan($service['domain_uuid']);$this->audit('service_package_assigned',['plan_uuid'=>$p['plan_uuid']],$service['domain_uuid'],$service['tenant_uuid']);$this->db->commit();}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
    }
    private function capacityDialplan(string $domain): void {
        $realm=$this->q('select domain_name from v_domains where domain_uuid=?',[$domain])->fetchColumn();$id=$this->q("select dialplan_uuid from v_dialplans where domain_uuid=? and dialplan_name='OpenWeb resource allowance'",[$domain])->fetchColumn();if($id)return;
        $doc=new DOMDocument('1.0','UTF-8');$extension=$doc->appendChild($doc->createElement('extension'));$extension->setAttribute('name','OpenWeb resource allowance');$extension->setAttribute('continue','true');$condition=$extension->appendChild($doc->createElement('condition'));foreach([['set','domain_uuid='.$domain],['lua','app.lua pbx_setup capacity']]as[$application,$data]){$a=$condition->appendChild($doc->createElement('action'));$a->setAttribute('application',$application);$a->setAttribute('data',$data);}$this->q("insert into v_dialplans(dialplan_uuid,domain_uuid,dialplan_name,dialplan_context,dialplan_order,dialplan_continue,dialplan_enabled,dialplan_xml,dialplan_description)values(?,?,'OpenWeb resource allowance',?,'001',true,true,?,'Resource package admission')",[uuid(),$domain,$realm,$doc->saveXML($extension)]);
    }
    public function usage(string $domain): array {$this->service($domain);$r=$this->q('select e.*,p.plan_name,p.extension_price_cents,p.call_price_cents,p.currency,(select count(*) from v_extensions x where x.domain_uuid=e.domain_uuid) extensions_used from v_pbx_service_entitlements e left join v_pbx_resource_plans p using(plan_uuid) where e.domain_uuid=?',[$domain])->fetch(PDO::FETCH_ASSOC);if(!$r)return ['domain_uuid'=>$domain,'legacy_unlimited'=>true,'extensions_used'=>(int)$this->q('select count(*) from v_extensions where domain_uuid=?',[$domain])->fetchColumn()];$r['extensions_allowed']=(int)$r['extension_limit']+(int)$r['extra_extensions'];$r['calls_allowed']=(int)$r['concurrent_calls']+(int)$r['extra_calls'];$r['legacy_unlimited']=false;$r['calls_in_use']=null;try{$v=trim(event_socket::api('limit_usage hash openweb-pbx-'.$domain.' calls'));if(ctype_digit($v))$r['calls_in_use']=(int)$v;}catch(Throwable){}return $r;}
    public function order(array $in): array {
        $actor=$this->actor();$service=$this->service($in['domain_uuid']??'');$ext=$this->integer($in,'extra_extensions',0,10000);$calls=$this->integer($in,'extra_calls',0,10000);if($ext+$calls===0)throw new InvalidArgumentException('Choose at least one additional resource.');$key=$in['idempotency_key']??'';if(!is_string($key)||!preg_match('/^[A-Za-z0-9_-]{8,100}$/D',$key))throw new InvalidArgumentException('Supply an order reference of 8 to 100 letters or numbers.');
        $this->db->beginTransaction();try{$e=$this->q('select e.*,p.extension_price_cents,p.call_price_cents,p.currency from v_pbx_service_entitlements e join v_pbx_resource_plans p using(plan_uuid) where e.domain_uuid=? for update of e',[$service['domain_uuid']])->fetch(PDO::FETCH_ASSOC);if(!$e)throw new DomainException('Ask your administrator to assign a resource package first.');$old=$this->q('select * from v_pbx_resource_orders where domain_uuid=? and idempotency_key=?',[$service['domain_uuid'],$key])->fetch(PDO::FETCH_ASSOC);if($old){if((int)$old['extra_extensions']!==$ext||(int)$old['extra_calls']!==$calls||$old['requested_by']!==$actor)throw new DomainException('This order reference was already used for a different request.');$this->db->commit();return $old;}
        if((int)$e['extra_extensions']+$ext>10000||(int)$e['extra_calls']+$calls>10000)throw new InvalidArgumentException('This request exceeds the supported package size.');$hosted=$this->policy()['hosted'];$cost=$hosted&&$e['billable']?$ext*(int)$e['extension_price_cents']+$calls*(int)$e['call_price_cents']:0;$id=uuid();$r=$this->q('insert into v_pbx_resource_orders(order_uuid,domain_uuid,requested_by,idempotency_key,extra_extensions,extra_calls,monthly_amount_cents,currency) values(?,?,?,?,?,?,?,?) returning *',[$id,$service['domain_uuid'],$actor,$key,$ext,$calls,$cost,$e['currency']])->fetch(PDO::FETCH_ASSOC);$this->audit('capacity_requested',['order_uuid'=>$id,'monthly_amount_cents'=>$cost],$service['domain_uuid'],$service['tenant_uuid']);$this->db->commit();return $r;}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
    }
    public function orders(?string $domain=null): array {$actor=$this->actor();if($domain!==null){$this->service($domain);return $this->q('select * from v_pbx_resource_orders where domain_uuid=? order by created_at desc limit 500',[$domain])->fetchAll(PDO::FETCH_ASSOC);}return $this->q('select o.*,s.service_name,t.tenant_name from v_pbx_resource_orders o join v_pbx_services s using(domain_uuid) join v_pbx_tenants t using(tenant_uuid) where '.($this->platform()?'true':($this->manager()?'(t.owner_user_uuid=? or t.reseller_user_uuid=?)':'t.owner_user_uuid=?')).' order by o.created_at desc limit 500',$this->platform()?[]:($this->manager()?[$actor,$actor]:[$actor]))->fetchAll(PDO::FETCH_ASSOC);}
    public function approve(string $id): void {$this->manage();$this->changeOrder($id,true);}
    public function cancel(string $id): void {$this->actor();$this->changeOrder($id,false);}
    private function changeOrder(string $id,bool $approve): void {
        $this->db->beginTransaction();try{$r=$this->q('select * from v_pbx_resource_orders where order_uuid=? for update',[$this->id($id)])->fetch(PDO::FETCH_ASSOC);if(!$r)throw new OutOfBoundsException('Order unavailable.');$s=$this->service($r['domain_uuid']);if(!$approve&&!$this->manager()&&$r['requested_by']!==$_SESSION['user_uuid'])throw new DomainException('Only the requester can cancel this order.');if($r['status']===($approve?'approved':'cancelled')){$this->db->commit();return;}if($r['status']!=='pending')throw new DomainException('This order has already been completed.');if($approve){if(!$this->platform()&&$s['owner_user_uuid']===($_SESSION['user_uuid']??''))throw new DomainException('Wholesale capacity must be approved by the instance administrator.');$held=$this->q('select * from v_pbx_service_entitlements where domain_uuid=? for update',[$r['domain_uuid']])->fetch(PDO::FETCH_ASSOC);if(!$held)throw new DomainException('The PBX resource package is no longer available.');if($held['restore_hold'])throw new DomainException('A backup restore is in progress. Try again when it finishes.');$this->withinCeiling((int)$held['extension_limit']+(int)$held['extra_extensions']+(int)$r['extra_extensions'],(int)$held['concurrent_calls']+(int)$held['extra_calls']+(int)$r['extra_calls']);$this->q('update v_pbx_service_entitlements set extra_extensions=extra_extensions+?,extra_calls=extra_calls+?,updated_at=now(),updated_by=? where domain_uuid=?',[(int)$r['extra_extensions'],(int)$r['extra_calls'],$_SESSION['user_uuid'],$r['domain_uuid']]);$this->q("update v_pbx_resource_orders set status='approved',approved_by=?,approved_at=now() where order_uuid=?",[$_SESSION['user_uuid'],$id]);}else $this->q("update v_pbx_resource_orders set status='cancelled' where order_uuid=?",[$id]);$this->audit($approve?'capacity_approved':'capacity_cancelled',['order_uuid'=>$id],$s['domain_uuid'],$s['tenant_uuid']);$this->db->commit();}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
    }
}
